package com.bank.payroll;

import java.math.BigDecimal;
import java.util.*;
import java.util.DoubleSummaryStatistics;
import java.util.logging.*;

public class SummaryStatsDemo {
    private static final Logger log = Logger.getLogger("Payroll");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> team = List.of(
            new Employee("Rajesh", new BigDecimal("1000000")),
            new Employee("Priya", new BigDecimal("250000")),
            new Employee("Amit", new BigDecimal("400000")));
        PayrollSummaryService service = new PayrollSummaryService();

        DoubleSummaryStatistics stats = service.summarize(team);
        log.info(() -> "count=" + stats.getCount() + " sum=" + stats.getSum()
            + " min=" + stats.getMin() + " max=" + stats.getMax()
            + " avg=" + stats.getAverage());
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final BigDecimal salary;
    Employee(String name, BigDecimal salary) { this.name = name; this.salary = salary; }
    double getSalaryAsDouble() { return salary.doubleValue(); }
}

// ─── Would be in service/PayrollSummaryService.java ───
class PayrollSummaryService {
    DoubleSummaryStatistics summarize(List<Employee> team) {
        return team.stream()
            .mapToDouble(Employee::getSalaryAsDouble)  // DoubleStream
            .summaryStatistics();                       // one pass → all five stats
    }
}
